#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT Shape : 4
COMPONENT Networking : 4
COMPONENT DIS : 2
COMPONENT Scripting : 1
COMPONENT KeyDeviceSensor : 1
COMPONENT EventUtilities : 1
COMPONENT Text : 2
COMPONENT X_ITE : 1

Viewpoint {
  position 0 0 8
}

Background {
  skyColor 0.15 0.15 0.18
}

DirectionalLight {
  intensity 0.9
  direction -0.4 -0.6 -0.7
}

Group {
  bboxSize 20 20 20
  children [
    ReceiverPdu {
      bboxDisplay TRUE
      bboxSize 2 1 1
      bboxCenter -3 2 0
    }
    SignalPdu {
      visible FALSE
      bboxDisplay TRUE
      bboxSize 1 2 1
      bboxCenter 0 2 0
    }
    TransmitterPdu {
      bboxDisplay TRUE
      bboxSize 1 1 3
      bboxCenter 3 2 0
    }
    ReceiverPdu {
      bboxDisplay TRUE
    }
    ReceiverPdu {
      bboxSize 1 1 1
      bboxCenter -3 -2 0
    }
    SignalPdu {
      bboxDisplay TRUE
      bboxSize 2 2 2
      bboxCenter 0 -2 0
      enabled FALSE
    }
    Transform {
      translation 3 -2 0
      rotation 0 1 0 0.6
      scale 1 2 1
      children [
        TransmitterPdu {
          bboxDisplay TRUE
          bboxSize 1 1 1
        }
        Shape {
          appearance Appearance {
            material Material {
              diffuseColor 0.3 0.8 0.3
            }
          }
          geometry Box {
            size 0.5 0.5 0.5
          }
        }
      ]
    }
  ]
}

